import sys
from functools import cmp_to_key

def compare_rows(row1, row2, col):
    if row1[col] == row2[col]:
        return 0
    return (row1[col] > row2[col]) - (row1[col] < row2[col])

def can_transform(A, B, n, m):
    steps = []
    for col in range(m):
        sorted_A = sorted(A, key=cmp_to_key(lambda x, y: compare_rows(x, y, col)))
        if sorted_A == B:
            steps.append(col + 1)
            return steps
        elif sorted_A == A:
            continue
        else:
            A = sorted_A
            steps.append(col + 1)
    return steps if A == B else []

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    m = int(input[idx + 1])
    idx += 2
    A = []
    for _ in range(n):
        A.append([int(input[idx + j]) for j in range(m)])
        idx += m
    B = []
    for _ in range(n):
        B.append([int(input[idx + j]) for j in range(m)])
       (idx += m)
    steps = can_transform(A, B, n, m)
    if not steps:
        print(-1)
    else:
        print(len(steps))
        print(' '.join(map(str, steps)))

main()
